// =============================================================================
// Testbench: winograd_core_tb
// Description: Automated Self-Checking Top-Level Regression Testbench
// Reads 50 test tiles from hex files generated by Python golden model.
// Evaluates cycle-by-cycle outputs and asserts zero bit-level mismatches.
// =============================================================================
`timescale 1ns / 1ps

module winograd_core_tb;

    parameter NUM_TILES = 50;
    parameter CIN = 1;
    parameter INSERT_GAPS = 0;
    parameter PARALLEL_DSPS = 16;
    string vector_dir = "tb";

    logic        clk;
    logic        rst_n;

    logic        in_valid;
    logic        in_ready;
    logic signed [15:0] d_tile [0:3][0:3];
    logic signed [15:0] u_tile [0:3][0:3];
    logic        first_ch;
    logic        last_ch;

    logic        out_valid;
    logic signed [15:0] y_tile [0:1][0:1];

    // DUT instantiation
    winograd_top #(
        .DATA_IN_WIDTH(16),
        .V_WIDTH(18),
        .U_WIDTH(16),
        .PROD_WIDTH(34),
        .MAX_CHANNELS(CIN),
        .DATA_OUT_WIDTH(16),
        .PARALLEL_DSPS(PARALLEL_DSPS)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .in_valid(in_valid),
        .in_ready(in_ready),
        .d_tile(d_tile),
        .u_tile(u_tile),
        .first_ch(first_ch),
        .last_ch(last_ch),
        .out_valid(out_valid),
        .y_tile(y_tile)
    );

    // Clock generation: 100MHz (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Test vector buffers
    logic [15:0] input_mem    [0:(NUM_TILES*CIN*16)-1];
    logic [15:0] weight_mem   [0:(NUM_TILES*CIN*16)-1];
    logic [15:0] expected_mem [0:(NUM_TILES*4)-1];

    int mismatch_count = 0;
    int verified_tiles = 0;

    // Output checking process
    initial begin
        int exp_idx = 0;
        while (verified_tiles < NUM_TILES) begin
            @(negedge clk);
            if (out_valid) begin
                for (int r = 0; r < 2; r++) begin
                    for (int c = 0; c < 2; c++) begin
                        logic signed [15:0] exp_val;
                        exp_val = expected_mem[exp_idx];
                        if (y_tile[r][c] !== exp_val) begin
                            $display("[MISMATCH] Tile %0d [%0d,%0d]: Got %0d (0x%04x), Expected %0d (0x%04x)",
                                verified_tiles, r, c, y_tile[r][c], y_tile[r][c], exp_val, exp_val);
                            mismatch_count++;
                        end
                        exp_idx++;
                    end
                end
                verified_tiles++;
                if (verified_tiles % 10 == 0) begin
                    $display("[TB INFO] Verified %0d / %0d tiles...", verified_tiles, NUM_TILES);
                end
            end
        end

        repeat (8) begin
            @(negedge clk);
            if (out_valid) $fatal(1, "Unexpected extra output tile");
        end
        $display("\n=======================================================");
        $display("          REGRESSION SIMULATION SUMMARY                ");
        $display("=======================================================");
        $display(" Total Tiles Tested   : %0d", NUM_TILES);
        $display(" Total Output Pixels  : %0d", NUM_TILES * 4);
        $display(" Total Mismatches     : %0d", mismatch_count);
        if (mismatch_count == 0) begin
            $display(" STATUS               : [PASSED] ZERO BIT MISMATCHES!  ");
        end else begin
            $fatal(1, "Mismatches detected: %0d", mismatch_count);
        end
        $display("=======================================================\n");

        $finish;
    end

    // Stimulus feeding process
    initial begin
        if (CIN < 1) $fatal(1, "CIN must be positive");
        void'($value$plusargs("VECTOR_DIR=%s", vector_dir));
        $display("[TB] Loading hex test vectors from %s (Cin=%0d, gaps=%0d)", vector_dir, CIN, INSERT_GAPS);
        $readmemh({vector_dir, "/input.hex"}, input_mem);
        $readmemh({vector_dir, "/weight.hex"}, weight_mem);
        $readmemh({vector_dir, "/expected_output.hex"}, expected_mem);
        $display("[TB] Test vectors loaded successfully.");

        rst_n = 0;
        in_valid = 0;
        first_ch = 0;
        last_ch  = 0;

        repeat (3) @(negedge clk);
        rst_n = 1;

        // Consecutive tiles exercise accumulator restart without draining the pipeline.
        for (int t = 0; t < NUM_TILES; t++) begin
            for (int ch = 0; ch < CIN; ch++) begin
                @(negedge clk);
                if (INSERT_GAPS && ((t + ch) % 3 == 1)) begin
                    in_valid = 0;
                    // Invalid markers must not change the accumulation state.
                    first_ch = 1;
                    last_ch = 1;
                    repeat (2) @(negedge clk);
                end
                if (!in_ready) $fatal(1, "Unexpected input stall");
                in_valid = 1;
                first_ch = (ch == 0);
                last_ch = (ch == CIN - 1);
                for (int r = 0; r < 4; r++) begin
                    for (int c = 0; c < 4; c++) begin
                        d_tile[r][c] = input_mem[(t*CIN+ch)*16 + r*4 + c];
                        u_tile[r][c] = weight_mem[(t*CIN+ch)*16 + r*4 + c];
                    end
                end
            end
        end
        @(negedge clk);
        in_valid = 0;
        first_ch = 0;
        last_ch = 0;
    end

    // Watchdog timer (prevent infinite hanging)
    initial begin
        #(1000 + NUM_TILES*CIN*40);
        $fatal(1, "Watchdog timeout: verified %0d / %0d tiles", verified_tiles, NUM_TILES);
    end

endmodule
